// Action function for rule: Grammar
fn onGrammar(c: *interpreter.Current, initializer: interpreter.Value, rules: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();

    // create the grammar, assign its initializer
    const g = try c.allocator.create(ast.Grammar);
    g.* = ast.Grammar{
        .pos = pos,
        .init = null,
        .rules = std.ArrayList(*ast.Rule).init(c.allocator),
    };

    if (initializer) |init_val| {
        g.init = @as(*ast.CodeBlock, @ptrCast(init_val));
    }

    const rules_slice = @as([]const []const u8, @ptrCast(rules));
    for (rules_slice) |rule_val| {
        const rule_ptr = @as(*ast.Rule, @ptrCast(rule_val));
        try g.rules.append(c.allocator, rule_ptr);
    }

    return g;

}

// Action function for rule: Initializer
fn onInitializer(c: *interpreter.Current, code: interpreter.Value) !interpreter.Value {
    _ = c;
    
    return code;

}

// Action function for rule: Rule
fn onRule(c: *interpreter.Current, name: interpreter.Value, display: interpreter.Value, expr: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();

    const rule = try c.allocator.create(ast.Rule);
    rule.* = ast.Rule{
        .pos = pos,
        .name = name.*,
        .display_name = undefined,
        .expression = undefined,
        .expr = undefined,
        .visited = false,
        .nullable = false,
        .left_recursive = false,
        .leader = false,
    };

    if (display) |display_val| {
        rule.display_name = @as(ast.StringLit, @ptrCast(display_val));
    } else {
        rule.display_name = ast.StringLit{
            .pos = pos,
            .value = "",
        };
    }

    const expr_ptr = try c.allocator.create(ast.Expression);
    expr_ptr.* = expr;
    rule.expr = expr_ptr;
    rule.expression = expr;

    return rule;

}

// Action function for rule: Expression
fn onExpression(c: *interpreter.Current) !interpreter.Value {
    _ = c;
}

// Action function for rule: ChoiceExpr
fn onChoiceExpr(c: *interpreter.Current, first: interpreter.Value, rest: interpreter.Value) !interpreter.Value {
    
    const rest_slice = @as([]const []const u8, @ptrCast(rest));
    if (rest_slice.len == 0) {
        return first;
    }

    const pos = c.astPos();
    const choice = try ast.ChoiceExpr.init(c.allocator, pos);
    try choice.alternatives.append(c.allocator, first);

    for (rest_slice) |sl| {
        const expr = @as(ast.Expression, @ptrCast(sl));
        try choice.alternatives.append(c.allocator, expr);
    }

    return ast.Expression{ .choice = choice };

}

// Action function for rule: ActionExpr
fn onActionExpr(c: *interpreter.Current, expr: interpreter.Value, code: interpreter.Value) !interpreter.Value {
    
    if (code == null) {
        return expr;
    }

    const pos = c.astPos();
    const act = try ast.ActionExpr.init(c.allocator, pos, expr, code.?, 0);
    return ast.Expression{ .action = act };

}

// Action function for rule: SeqExpr
fn onSeqExpr(c: *interpreter.Current, first: interpreter.Value, rest: interpreter.Value) !interpreter.Value {
    
    const rest_slice = @as([]const []const u8, @ptrCast(rest));
    if (rest_slice.len == 0) {
        return first;
    }
    const seq = try ast.SeqExpr.init(c.allocator, c.astPos());
    try seq.exprs.append(c.allocator, first);
    for (rest_slice) |sl| {
        const expr = @as(ast.Expression, @ptrCast(sl));
        try seq.exprs.append(c.allocator, expr);
    }
    return ast.Expression{ .seq = seq };

}

// Action function for rule: LabeledExpr
fn onLabeledExpr(c: *interpreter.Current, label: interpreter.Value, expr: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();
    const lab = try c.allocator.create(ast.LabeledExpr);
    const label_ptr = try c.allocator.create(ast.Identifier);
    label_ptr.* = label.*;
    const expr_ptr = try c.allocator.create(ast.Expression);
    expr_ptr.* = expr;

    lab.* = ast.LabeledExpr{
        .pos = pos,
        .label = label_ptr,
        .expr = expr_ptr,
    };
    return ast.Expression{ .labeled = lab };

}

// Action function for rule: PrefixedExpr
fn onPrefixedExpr(c: *interpreter.Current, op: interpreter.Value, expr: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();
    const op_str = @as([]const u8, @ptrCast(op));
    if (std.mem.eql(u8, op_str, "&")) {
        const and_expr = try ast.AndExpr.init(c.allocator, pos, expr);
        return ast.Expression{ .and_expr = and_expr };
    }
    const not_expr = try c.allocator.create(ast.NotExpr);
    const expr_ptr = try c.allocator.create(ast.Expression);
    expr_ptr.* = expr;
    not_expr.* = ast.NotExpr{
        .pos = pos,
        .expr = expr_ptr,
    };
    return ast.Expression{ .not = not_expr };

}

// Action function for rule: PrefixedOp
fn onPrefixedOp(c: *interpreter.Current) !interpreter.Value {
    
    return c.text;

}

// Action function for rule: SuffixedExpr
fn onSuffixedExpr(c: *interpreter.Current, expr: interpreter.Value, op: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();
    const op_str = @as([]const u8, @ptrCast(op));
    const expr_ptr = try c.allocator.create(ast.Expression);
    expr_ptr.* = expr;

    if (std.mem.eql(u8, op_str, "?")) {
        const zero_or_one = try c.allocator.create(ast.ZeroOrOneExpr);
        zero_or_one.* = ast.ZeroOrOneExpr{
            .pos = pos,
            .expr = expr_ptr,
        };
        return ast.Expression{ .zero_or_one = zero_or_one };
    } else if (std.mem.eql(u8, op_str, "*")) {
        const zero_or_more = try c.allocator.create(ast.ZeroOrMoreExpr);
        zero_or_more.* = ast.ZeroOrMoreExpr{
            .pos = pos,
            .expr = expr_ptr,
        };
        return ast.Expression{ .zero_or_more = zero_or_more };
    } else if (std.mem.eql(u8, op_str, "+")) {
        const one_or_more = try c.allocator.create(ast.OneOrMoreExpr);
        one_or_more.* = ast.OneOrMoreExpr{
            .pos = pos,
            .expr = expr_ptr,
        };
        return ast.Expression{ .one_or_more = one_or_more };
    } else {
        return error.UnknownOperator;
    }

}

// Action function for rule: SuffixedOp
fn onSuffixedOp(c: *interpreter.Current) !interpreter.Value {
    
    return c.text;

}

